-- reglas_intro_cards
INSERT INTO convocatoria_content (torneoid, section_id, section_type, content, enabled) VALUES (346, 'reglas_intro_cards', 'cards', '[{"icon": "BookOpen", "title": "Reglas USGA / FMG", "body": "Se jugará bajo las reglas de la USGA adoptadas por la Federación Mexicana de Golf, así como las reglas locales y términos de la competencia que se publicarán para el torneo."}, {"icon": "Scale", "title": "Sistema de Handicap", "body": "Se utiliza el hándicap registrado en FMG o en el sistema interno del club publicado al 1° de abril de 2026. Las categorías que aplican hándicap juegan al 80% de su H.I."}]', 1, 1)
ON DUPLICATE KEY UPDATE
  section_type = 'cards',
  content = '[{"icon": "BookOpen", "title": "Reglas USGA / FMG", "body": "Se jugará bajo las reglas de la USGA adoptadas por la Federación Mexicana de Golf, así como las reglas locales y términos de la competencia que se publicarán para el torneo."}, {"icon": "Scale", "title": "Sistema de Handicap", "body": "Se utiliza el hándicap registrado en FMG o en el sistema interno del club publicado al 1° de abril de 2026. Las categorías que aplican hándicap juegan al 80% de su H.I."}]',
  enabled = 1,
  display_order = 1,
  updated_at = CURRENT_TIMESTAMP;

-- reglas_locales
INSERT INTO convocatoria_content (torneoid, section_id, section_type, content, enabled) VALUES (346, 'reglas_locales', 'accordion', '[{"titulo": "Reglas de juego", "contenido": "Se jugará bajo las reglas de la USGA adoptadas por la Federación Mexicana de Golf, así como las reglas locales y términos de la competencia que se publicarán para el torneo."}, {"titulo": "Resolución de controversias", "contenido": "Las controversias que se originen sobre cualquier punto relacionado con la aplicación de las reglas serán resueltas por el Oficial de Reglas y/o el Comité Organizador y su fallo será definitivo e inapelable."}, {"titulo": "Rondas estipuladas", "contenido": "Las rondas de juego estipuladas para este torneo son de 9 hoyos."}, {"titulo": "Marcas de salida — Damas", "contenido": "Categorías A, B, C, D y E: marcas Rojas. Estelares: marcas Naranjas."}, {"titulo": "Marcas de salida — Caballeros", "contenido": "Campeonato: marcas Negras. Premier y AA: marcas Azules. A, B, C y D: marcas Blancas."}, {"titulo": "Marcas de salida — Seniors", "contenido": "Campeonato Mayores: marcas Blancas. A y B: marcas Doradas."}, {"titulo": "Horarios de salida", "contenido": "Las salidas del turno matutino serán a partir de las 06:10 hrs. Las salidas del turno vespertino serán a partir de las 11:00 hrs."}, {"titulo": "Cuestiones climatológicas", "contenido": "Si por cuestiones climatológicas no se logran jugar dos rondas de 18 hoyos, el comité organizador decidirá a cuántos hoyos se hará el corte."}, {"titulo": "Cupos por categoría", "contenido": "Si una categoría alcanza el número máximo de jugadores, se cerrará y los jugadores que queden fuera entrarán a una lista de espera. Si hay alguna cancelación o espacio disponible, se llamará al jugador para que pueda inscribirse y forme parte del field del torneo."}]', 1, 2)
ON DUPLICATE KEY UPDATE
  section_type = 'accordion',
  content = '[{"titulo": "Reglas de juego", "contenido": "Se jugará bajo las reglas de la USGA adoptadas por la Federación Mexicana de Golf, así como las reglas locales y términos de la competencia que se publicarán para el torneo."}, {"titulo": "Resolución de controversias", "contenido": "Las controversias que se originen sobre cualquier punto relacionado con la aplicación de las reglas serán resueltas por el Oficial de Reglas y/o el Comité Organizador y su fallo será definitivo e inapelable."}, {"titulo": "Rondas estipuladas", "contenido": "Las rondas de juego estipuladas para este torneo son de 9 hoyos."}, {"titulo": "Marcas de salida — Damas", "contenido": "Categorías A, B, C, D y E: marcas Rojas. Estelares: marcas Naranjas."}, {"titulo": "Marcas de salida — Caballeros", "contenido": "Campeonato: marcas Negras. Premier y AA: marcas Azules. A, B, C y D: marcas Blancas."}, {"titulo": "Marcas de salida — Seniors", "contenido": "Campeonato Mayores: marcas Blancas. A y B: marcas Doradas."}, {"titulo": "Horarios de salida", "contenido": "Las salidas del turno matutino serán a partir de las 06:10 hrs. Las salidas del turno vespertino serán a partir de las 11:00 hrs."}, {"titulo": "Cuestiones climatológicas", "contenido": "Si por cuestiones climatológicas no se logran jugar dos rondas de 18 hoyos, el comité organizador decidirá a cuántos hoyos se hará el corte."}, {"titulo": "Cupos por categoría", "contenido": "Si una categoría alcanza el número máximo de jugadores, se cerrará y los jugadores que queden fuera entrarán a una lista de espera. Si hay alguna cancelación o espacio disponible, se llamará al jugador para que pueda inscribirse y forme parte del field del torneo."}]',
  enabled = 1,
  display_order = 2,
  updated_at = CURRENT_TIMESTAMP;

-- reglamento_local
INSERT INTO convocatoria_content (torneoid, section_id, section_type, content, enabled) VALUES (346, 'reglamento_local', 'accordion', '[{"titulo": "Caballeros — Campeonato, Premier y AA", "contenido": "Stroke Play sin hándicap. Jugarán a 54 hoyos. Habrá corte a los 36 hoyos jugados. Pasarán a la final los mejores 12 jugadores sin empates. Cupo limitado a 36 jugadores por categoría."}, {"titulo": "Caballeros — Categoría A", "contenido": "Stroke Play sin hándicap. Edad 18 o más. Jugarán a 72 hoyos. Habrá 2 cortes: el primero a los 36 hoyos jugados pasando los mejores 24 jugadores sin empates, y el segundo a 54 hoyos jugados pasando a la final los primeros 12 jugadores sin empates. Cupo limitado a 80 jugadores."}, {"titulo": "Caballeros — Categorías B, C y D", "contenido": "Stableford acumulado al 80% del hándicap. Edad 18 o más. Jugarán a 72 hoyos. Habrá 2 cortes: el primero a los 36 hoyos jugados pasando los mejores 24 sin empates y el segundo a 54 hoyos pasando a la final los primeros 12 sin empates. Cupos: B y C 96 jugadores, D 80 jugadores."}, {"titulo": "Seniors — Campeonato Mayores", "contenido": "Stroke Play al 80% del hándicap. Jugarán a 54 hoyos. Corte a los 36 hoyos. Los mejores 4 jugadores Gross y los mejores 4 Neto jugarán la final sin empates. Deberán tener 50 años cumplidos al primer día de juego. Jugarán de marcas blancas con su hándicap correspondiente. Si un jugador gana la final Gross y también la Neto, sólo recibirá el trofeo Gross. Cupo limitado a 16 jugadores."}, {"titulo": "Seniors — A y B", "contenido": "Stableford al 80% del hándicap. Jugarán a 54 hoyos. Corte a los 36 hoyos. Los mejores 12 jugadores sin empates de cada categoría jugarán la final conservando el acumulado de puntos. Deberán tener 60 años cumplidos al primer día de juego. Jugarán de marcas doradas. Las categorías se dividirán en base al H.I. según los inscritos. Cupo límite entre A y B: 56 jugadores."}, {"titulo": "Damas — A y B", "contenido": "Stroke Play al 80% del hándicap. Jugarán a 54 hoyos. Corte a los 36 hoyos. Las mejores 4 jugadoras Gross y las mejores 4 Neto sin empates jugarán la final. Si una jugadora pasa a la final Gross y también a la Neto, sólo jugará por el trofeo Gross; en ese caso la quinta mejor jugadora (en Neto) jugará por el trofeo Neto."}, {"titulo": "Damas — C, D y E", "contenido": "Stableford al 80% del hándicap. Jugarán a 54 hoyos. Corte a los 36 hoyos. Las mejores 8 jugadoras sin empates pasarán a la final conservando el acumulado de puntos. Cupo limitado entre A, B, C, D y E: 100 jugadoras."}, {"titulo": "Damas Estelares", "contenido": "Jugarán a 27 hoyos sin hándicap. Corte a los 18 hoyos. Pasarán las mejores 6 jugadoras sin empates conservando el acumulado de puntos a la ronda final. Cupo límite: 12 jugadoras."}, {"titulo": "Rangos de hándicap — Caballeros", "contenido": "Campeonato: hasta 0.9 · Premier: 1.0 a 3.9 · AA: 4.0 a 7.0 · A: 7.1 a 11.3 · B: 11.4 a 15.8 · C: 15.9 a 21.2 · D: 21.3 a 28.4."}, {"titulo": "Rangos de hándicap — Seniors", "contenido": "Campeonato Mayores: hasta 9.5 · A / B: 0 a 34.6 (A y B se dividirán entre los inscritos en base al H.I.)."}, {"titulo": "Rangos de hándicap — Damas", "contenido": "A: hasta 13.5 · B: 13.6 a 17.9 · C: 18.0 a 22.3 · D: 22.4 a 27.6 · E: 27.7 a 35.5 · Estelares: sin H.C.P."}, {"titulo": "Desempates para corte", "contenido": "Primer término: ganará el jugador con mejor score del último día. Segundo término: se tomará la tarjeta del último día para desempatar por el sistema de comparación de tarjetas (9-6-3-1), de la vuelta del hoyo 10 al 18. En caso de persistir el empate, se hará lo mismo para la 1ª vuelta."}, {"titulo": "Desempates para trofeos", "contenido": "Solo para el primer lugar en todas las categorías Gross o Neto se jugará a muerte súbita sin ventajas. El resto de los empates se definirá en primer término por el mejor score del último día. En segundo término, por comparación de tarjetas del último día del hoyo 10 al 18 bajo el sistema 9-6-3-1."}, {"titulo": "Nota importante sobre el corte", "contenido": "El jugador que no pasó el corte, una vez publicadas las listas de resultados, no podrá participar en la ronda final por ningún motivo. En el caso de jugadores participando en dos categorías, si pasan el corte en ambas, el jugador deberá dar aviso al final aclarando cuál de las dos categorías quiere jugar para la ronda final."}]', 1, 3)
ON DUPLICATE KEY UPDATE
  section_type = 'accordion',
  content = '[{"titulo": "Caballeros — Campeonato, Premier y AA", "contenido": "Stroke Play sin hándicap. Jugarán a 54 hoyos. Habrá corte a los 36 hoyos jugados. Pasarán a la final los mejores 12 jugadores sin empates. Cupo limitado a 36 jugadores por categoría."}, {"titulo": "Caballeros — Categoría A", "contenido": "Stroke Play sin hándicap. Edad 18 o más. Jugarán a 72 hoyos. Habrá 2 cortes: el primero a los 36 hoyos jugados pasando los mejores 24 jugadores sin empates, y el segundo a 54 hoyos jugados pasando a la final los primeros 12 jugadores sin empates. Cupo limitado a 80 jugadores."}, {"titulo": "Caballeros — Categorías B, C y D", "contenido": "Stableford acumulado al 80% del hándicap. Edad 18 o más. Jugarán a 72 hoyos. Habrá 2 cortes: el primero a los 36 hoyos jugados pasando los mejores 24 sin empates y el segundo a 54 hoyos pasando a la final los primeros 12 sin empates. Cupos: B y C 96 jugadores, D 80 jugadores."}, {"titulo": "Seniors — Campeonato Mayores", "contenido": "Stroke Play al 80% del hándicap. Jugarán a 54 hoyos. Corte a los 36 hoyos. Los mejores 4 jugadores Gross y los mejores 4 Neto jugarán la final sin empates. Deberán tener 50 años cumplidos al primer día de juego. Jugarán de marcas blancas con su hándicap correspondiente. Si un jugador gana la final Gross y también la Neto, sólo recibirá el trofeo Gross. Cupo limitado a 16 jugadores."}, {"titulo": "Seniors — A y B", "contenido": "Stableford al 80% del hándicap. Jugarán a 54 hoyos. Corte a los 36 hoyos. Los mejores 12 jugadores sin empates de cada categoría jugarán la final conservando el acumulado de puntos. Deberán tener 60 años cumplidos al primer día de juego. Jugarán de marcas doradas. Las categorías se dividirán en base al H.I. según los inscritos. Cupo límite entre A y B: 56 jugadores."}, {"titulo": "Damas — A y B", "contenido": "Stroke Play al 80% del hándicap. Jugarán a 54 hoyos. Corte a los 36 hoyos. Las mejores 4 jugadoras Gross y las mejores 4 Neto sin empates jugarán la final. Si una jugadora pasa a la final Gross y también a la Neto, sólo jugará por el trofeo Gross; en ese caso la quinta mejor jugadora (en Neto) jugará por el trofeo Neto."}, {"titulo": "Damas — C, D y E", "contenido": "Stableford al 80% del hándicap. Jugarán a 54 hoyos. Corte a los 36 hoyos. Las mejores 8 jugadoras sin empates pasarán a la final conservando el acumulado de puntos. Cupo limitado entre A, B, C, D y E: 100 jugadoras."}, {"titulo": "Damas Estelares", "contenido": "Jugarán a 27 hoyos sin hándicap. Corte a los 18 hoyos. Pasarán las mejores 6 jugadoras sin empates conservando el acumulado de puntos a la ronda final. Cupo límite: 12 jugadoras."}, {"titulo": "Rangos de hándicap — Caballeros", "contenido": "Campeonato: hasta 0.9 · Premier: 1.0 a 3.9 · AA: 4.0 a 7.0 · A: 7.1 a 11.3 · B: 11.4 a 15.8 · C: 15.9 a 21.2 · D: 21.3 a 28.4."}, {"titulo": "Rangos de hándicap — Seniors", "contenido": "Campeonato Mayores: hasta 9.5 · A / B: 0 a 34.6 (A y B se dividirán entre los inscritos en base al H.I.)."}, {"titulo": "Rangos de hándicap — Damas", "contenido": "A: hasta 13.5 · B: 13.6 a 17.9 · C: 18.0 a 22.3 · D: 22.4 a 27.6 · E: 27.7 a 35.5 · Estelares: sin H.C.P."}, {"titulo": "Desempates para corte", "contenido": "Primer término: ganará el jugador con mejor score del último día. Segundo término: se tomará la tarjeta del último día para desempatar por el sistema de comparación de tarjetas (9-6-3-1), de la vuelta del hoyo 10 al 18. En caso de persistir el empate, se hará lo mismo para la 1ª vuelta."}, {"titulo": "Desempates para trofeos", "contenido": "Solo para el primer lugar en todas las categorías Gross o Neto se jugará a muerte súbita sin ventajas. El resto de los empates se definirá en primer término por el mejor score del último día. En segundo término, por comparación de tarjetas del último día del hoyo 10 al 18 bajo el sistema 9-6-3-1."}, {"titulo": "Nota importante sobre el corte", "contenido": "El jugador que no pasó el corte, una vez publicadas las listas de resultados, no podrá participar en la ronda final por ningún motivo. En el caso de jugadores participando en dos categorías, si pasan el corte en ambas, el jugador deberá dar aviso al final aclarando cuál de las dos categorías quiere jugar para la ronda final."}]',
  enabled = 1,
  display_order = 3,
  updated_at = CURRENT_TIMESTAMP;

-- codigo_conducta
INSERT INTO convocatoria_content (torneoid, section_id, section_type, content, enabled) VALUES (346, 'codigo_conducta', 'accordion', '[{"icon": "Clock", "titulo": "Puntualidad", "contenido": "Los jugadores deberán presentarse en su hoyo de salida 5 minutos antes de la hora programada y estar listos para jugar a la hora estipulada. Si el jugador se presenta hasta con cinco minutos de retraso a su mesa de salida, tendrá 2 golpes de penalidad en el primer hoyo. Después de estos 5 minutos será descalificado."}, {"icon": "AlertTriangle", "titulo": "Ritmo de Juego", "contenido": "El tiempo máximo para completar 18 hoyos será de 4 horas y 40 minutos. Los grupos fuera de posición serán cronometrados con un máximo de 40 segundos por golpe. Penalidad: 1er mal tiempo, un golpe de castigo; 2do mal tiempo, penalidad general; 3er mal tiempo, descalificación."}, {"icon": "ScrollText", "titulo": "Código de Vestimenta", "contenido": "Vestimenta según el código interno del Reglamento de Golf del club: playera con cuello, pantalón o bermuda de vestir, y zapatos de golf. No se permiten jeans, playeras sin cuello o sandalias."}, {"icon": "Gavel", "titulo": "Dispositivos Electrónicos", "contenido": "Se permite el uso de dispositivos de medición de distancia. Queda prohibido utilizar funciones que midan velocidad del viento, slope u otros parámetros (Regla 4.3a). El uso de teléfonos celulares está permitido siempre que sea con discreción, sin retrasar el juego ni distraer a los demás jugadores. Durante la ronda está prohibido escuchar música (1ª infracción: amonestación; 2ª: penalidad general; 3ª: descalificación)."}, {"icon": "BookOpen", "titulo": "Transportación y Caddie", "contenido": "Los jugadores podrán utilizar transportación automotriz para ellos mismos, su equipo y su caddie. Es obligatorio contratar los servicios de un caddie (siempre y cuando el club pueda proporcionarlo), el cual puede ser compartido con otro jugador."}, {"icon": "Scale", "titulo": "Conducta Deportiva", "contenido": "Se espera que todos los participantes mantengan una conducta deportiva ejemplar. Cualquier comportamiento antideportivo será sancionado y puede resultar en descalificación. El comité Organizador se reserva el derecho de hacer cualquier cambio que juzgue necesario para el mejor desarrollo del torneo y cualquier punto no previsto en la presente convocatoria, o que no esté redactado con claridad, será resuelto por el Comité Organizador y su decisión será inapelable."}]', 1, 4)
ON DUPLICATE KEY UPDATE
